// Make the tests (the checks) pass, one at a time.
// balances: { name: cents }. Positive = is owed money, negative = owes.
// Return transfers: [{ from, to, amountCents }].
function settleUp(balances) {
  const entries = Object.entries(balances);
  const sum = entries.reduce((total, [, cents]) => total + cents, 0);
  if (sum !== 0) throw new Error('Balances must add up to zero');

  const debtors = [];
  const creditors = [];
  for (const [name, cents] of entries) {
    if (cents < 0) debtors.push({ name, cents: -cents });
    else if (cents > 0) creditors.push({ name, cents });
  }
  const largestFirst = (a, b) => b.cents - a.cents || a.name.localeCompare(b.name);
  debtors.sort(largestFirst);
  creditors.sort(largestFirst);

  const transfers = [];
  let d = 0;
  let c = 0;
  while (d < debtors.length && c < creditors.length) {
    const amountCents = Math.min(debtors[d].cents, creditors[c].cents);
    transfers.push({ from: debtors[d].name, to: creditors[c].name, amountCents });
    debtors[d].cents -= amountCents;
    creditors[c].cents -= amountCents;
    if (debtors[d].cents === 0) d += 1;
    if (creditors[c].cents === 0) c += 1;
  }
  return transfers;
}

console.log(settleUp({ Ana: 500, Ben: -500 }));
console.log(settleUp({ Ana: 1500, Ben: -1000, Cai: -500 }));

