const cases = [
  { Ana: 500, Ben: -500 },
  { Ana: 1500, Ben: -1000, Cai: -500 },
  { Ana: -700, Ben: 300, Cai: 400, Dee: 0 },
  { Ana: 2500, Ben: -1000, Cai: -1000, Dee: -1000, Eve: 500 },
  { Ana: -1, Ben: -1, Cai: 2 },
];
for (const b of cases) {
  const left = { ...b };
  const t = settleUp({ ...b });
  if (!Array.isArray(t) || (t.length === 0)) return false;
  for (const x of t) {
    if (!Number.isInteger(x.amountCents) || x.amountCents <= 0) return false;
    if (!(x.from in left) || !(x.to in left)) return false;
    left[x.from] += x.amountCents;
    left[x.to] -= x.amountCents;
  }
  if (Object.values(left).some((v) => v !== 0)) return false;
}
return true;

const cases = [
  { Ana: 500, Ben: -500 },
  { Ana: 1500, Ben: -1000, Cai: -500 },
  { Ana: -700, Ben: 300, Cai: 400, Dee: 0 },
  { Ana: 2500, Ben: -1000, Cai: -1000, Dee: -1000, Eve: 500 },
  { Ana: -1, Ben: -1, Cai: 2 },
];
return cases.every((b) => {
  const people = Object.values(b).filter((v) => v !== 0).length;
  const t = settleUp({ ...b });
  return Array.isArray(t) && t.length >= 1 && t.length <= people - 1;
});
